  /** Built-in validator names accepted by `Validators.validate` (string form). */
  export type ListsCoreFieldValidatorKey = 'integer' | 'number' | 'required';

  /** Masker names accepted by `Maskers.mask`. */
  export type ListsCoreMaskerKey =
    | 'integer'
    | 'number'
    | 'strictInteger'
    | 'strictNumber';

  /** Messages produced by built-in validators in lists-core. */
  export type ListsCoreBuiltInValidationError =
    | 'invalid number'
    | 'invalid whole number'
    | 'is required';

  export type ListsCoreValidatorFnParams = {
    errors: string[];
    object: Record<string, unknown>;
    value: unknown;
  };

  /** Custom validator hook used by `Validators.validate`. */
  export type ListsCoreValidatorFn = (
    params: ListsCoreValidatorFnParams,
  ) => string[];

  export function validate(
    validators: (ListsCoreFieldValidatorKey | ListsCoreValidatorFn)[],
    value: unknown,
    object?: Record<string, unknown>,
  ): string[];

  export const Validators: {
    ERRORS: {
      invalidInteger: 'invalid whole number';
      invalidNumber: 'invalid number';
      isRequired: 'is required';
    };
    OPTIONS: {
      integer: 'integer';
      number: 'number';
      required: 'required';
    };
    validate: typeof validate;
  };

  export function mask(maskers: ListsCoreMaskerKey[], value: unknown): unknown;

  export const Maskers: {
    OPTIONS: {
      integer: 'integer';
      number: 'number';
      strictInteger: 'strictInteger';
      strictNumber: 'strictNumber';
    };
    mask: typeof mask;
  };

  export const uuid: () => string;
